        let ts2 = ThreadState { segments: new_segments, .. ts };
        add thread_local_state += [ thread_id => ts2 ];
        add thread_of_segment += [ real_segment_id => thread_id ]
          by { lemma_segment_get_unused_uniq_field(pre.thread_of_segment.dom()); };
    }
}

